            "p": "Saju-Link называет человека, у которого стебель дня 己, так: «Инь-Земля (己)», а строка, которую показывает экран результата, такова: «Почва поля. Принимает все, что придет, и растит; скорее ухаживает, чем показывает.» Эта строка не связана с приведённым ниже чтением и баллами."
